        "**民法第 129 條第 1 項第 1 款**：消滅時效因「請求」而中斷。\n**民法第 130 條**：「時效因請求而中斷者，若於請求後 6 個月內不起訴，視為不中斷。」\n\n- **D 對**：存證信函屬「請求」（§129 I 1）→ 暫時中斷。但 §130 要求 6 個月內配合起訴方能確定中斷效力。本題 113/10/1 起算 6 個月至 114/4/1 屆滿，甲於 114/5/1 起訴已逾期 → §130 視為**自始未中斷**，原時效於 113/12/31 完成，乙得抗辯。\n- A 錯：忽略 §130 6 個月之限制。\n- B 錯：「請求」與「起訴」係不同事由，存證信函非起訴。\n- C 錯：請求中斷 + 6 個月內起訴之機制本即用以延展原時效。",
