      options: [
        { key: "A", text: "A 僅得依 §354 物之瑕疵擔保請求減少伺服器之價金之規定之效力。" },
        { key: "B", text: "A 僅能依 §184 主張侵權，不得同時依契約規定請求。" },
        { key: "C", text: "B 之損害賠償責任應以伺服器之買賣價金為上限額。" },
        { key: "D", text: "屬 §227 II 加害給付，固有利益損害與 §184 競合。" },
      ],
      correctAnswer: "D",
      explanationMd:
        "**民法第 227 條**：「因可歸責於債務人之事由，致為不完全給付者，債權人得依關於給付遲延或給付不能之規定行使其權利。**因不完全給付而生前項以外之損害者，債權人並得請求賠償**。」\n\n- **D 對**：交付伺服器有瑕疵 → 履行利益（伺服器本身）走 §354 / §227 I；資料庫毀損屬「固有利益」之損害 → §227 II 加害給付。同時 §184 I 前段（侵害財產權）亦可成立 → 請求權競合，A 可擇對其有利者主張（§125 一般 15 年 vs. §197 侵權 2/10 年）。\n- A 錯：忽略加害給付之賠償範圍。\n- B 錯：契約與侵權請求權競合，可並行。\n- C 錯：§216 損害賠償範圍以填補實際損害，不以價金為限。",
