        "**民法第 222 條**：「故意或重大過失之責任，不得預先免除。」\n\n- **B 對**：§222 為強行規定，免除故意 / 重大過失之約定該部分無效（§71）；契約其他部分（如就一般過失 / 輕過失之免責）原則上仍有效（§111 一部無效之分離）。\n- A 錯：契約自由受 §222 強行規定限制。\n- C 錯：§111 但書 — 除去無效部分契約亦可成立者，其他部分仍有效。\n- D 錯：§222 適用所有契約，不限消費關係。",
