      correctAnswer: "B",
      explanationMd:
        "**民法第 949 條第 1 項**：「占有物如係盜贓、遺失物或其他非基於原占有人之意思而喪失其占有者，原占有人自喪失占有之時起 2 年以內，得向善意受讓之現占有人請求回復其物。」\n**民法第 950 條**：「盜贓、遺失物或其他非基於原占有人之意思而喪失其占有之物，如現占有人由公開交易場所，或由販賣與其物同種之物之商人，以善意買得者，非償還其支付之價金，不得回復其物。」\n\n- **B 對**：機車為盜贓物，§949 給甲 2 年內向現占有人丙請求回復之超級特權。\n- A 錯：忽略 §949 對善意取得之限縮。\n- C 錯：§950 限「公開交易場所」或「販賣同種商品之商人」始適用價金償還；題目明確「非公開拍賣場所」 → §950 適用須個案判斷，本題未提及丙之店面為「販賣機車之商人」，題幹簡化下不適用 §950。\n- D 錯：忽略 §949 對盜贓物之特別規定。",
