      questionMd:
        "甲對 A 提起誣告，使 A 遭檢察官以詐欺罪起訴。於 A 詐欺案判決確定前，甲向檢察官自白其誣告行為。下列關於甲應否依刑法第 172 條減免其刑之審查，何者最為正確？",
      options: [
        { key: "A", text: "誣告罪一經起訴即無減免其刑之適用，甲應依 §169 I 處罰。" },
        { key: "B", text: "甲之自白屬阻卻違法事由，誣告罪自始不成立。" },
        { key: "C", text: "甲於誣告之案件裁判確定前自白，依 §172 減輕或免除其刑。" },
        { key: "D", text: "§172 自白須於起訴前為之，甲已逾該時點不得適用。" },
      ],
      correctAnswer: "C",
      explanationMd:
        "**刑法第 172 條**（偽證、誣告自白減免）：「犯第一百六十八條至第一百七十一條之罪，於所**虛偽陳述或所誣告之案件**，裁判或懲戒處分**確定前自白者**，**減輕或免除其刑**。」\n\n**§169 與 §172 之分工**：\n- **§169 I**：意圖他人受刑事或懲戒處分，向該管公務員誣告者，處七年以下有期徒刑（誣告罪本體）。\n- **§169 II**：以偽造、變造之證據或使用偽造、變造之證據誣告者，亦同（加重情形）。\n- **§172**：自白減免之**獨立規定**，適用於 §168（偽證）至 §171（未指定犯人誣告）之**全部誣告 / 偽證罪**。\n\n要件（§172）：\n1. 行為人已成立 §168–§171 之罪（本題甲成立 §169 I）。\n2. **時間點**：在所誣告（或虛偽陳述）之案件**裁判（或懲戒處分）確定前**。\n3. **方式**：自白其誣告（或偽證）行為。\n\n法律效果：**減輕或免除其刑**（必減事由）。\n\n本題：\n- A 詐欺案尚未判決確定。\n- 甲於該時點前向檢察官自白誣告。\n- → §172 之要件具備，得減輕或免除其刑。\n\n立法目的：鼓勵誣告者及早澄清，避免被誣告人受冤獄（呼應對被害人之保護）。\n\n- **C 對**：§172 為誣告罪自白減免之正確依據；本題甲於裁判確定前自白，符合要件。\n- **A 錯**：§172 明文減免規定，非「一經起訴即無減免」。\n- **B 錯**：誣告罪仍成立，自白僅減免其刑，非阻卻違法事由。\n- **D 錯**：§172 之時點為「裁判（懲戒處分）確定前」，非「起訴前」；甲於 A 詐欺案確定前自白，仍在期間內。",
