      correctAnswer: "B",
      explanationMd:
        "**客觀處罰條件 vs 加重結果犯 §17 之核心區別**：\n\n| 項目 | 客觀處罰條件 | 加重結果犯 §17 |\n|---|---|---|\n| 位階 | 處罰可能性階段（TB / RW / S 三階段之外） | 構成要件層次（基礎犯罪 + 加重結果） |\n| 故意 | **不要求**對該條件有認識 | 對加重結果須有「**客觀可預見性**」 |\n| 預見可能性 | 不要求 | **§17 反面要件** — 不能預見者不適用加重 |\n| 例 | §283「致人於死或重傷」、§238「致婚姻無效裁判確定」 | §277 II 傷害致死、§278 II 重傷致死 |\n\n本題核心：**§17 加重結果犯要求「能預見」**（依罪責原則），不能預見者不適用加重；客觀處罰條件則完全不適用此要求（這也是學說對客觀處罰條件「無責任處罰」之批判點，謝煜偉等學者傾向構成要件化）。\n\n- **B 對**：正確區分二者於「預見可能性」上之差別。\n- **A 錯**：客觀處罰條件依通說不要求故意。\n- **C 錯**：完全顛倒。\n- **D 錯**：二者皆非阻卻違法事由，位階亦不同。",
