      correctAnswer: ["A", "B", "C"],
      explanationMd:
        "**113 年憲判字第 8 號**（2024 死刑釋憲案）之核心意旨：\n\n1. 罪責原則 = 憲法層次原則。「刑罰以責任為基礎並受責任主義之拘束。」\n2. 罪責三層次內涵：\n   - 故意 / 過失之心理面。\n   - 不法意識（可能性）。\n   - 依其辨識而行為之能力（含責任能力 §18-§20、期待可能性）。\n3. 死刑限制：\n   - 須最嚴重之犯罪。\n   - 須三審強制辯護、合議庭一致決。\n   - **§19 II 限制責任能力者不得判死**。\n\n- **A 對**：完整列舉罪責三層次。\n- **B 對**：113 憲判 8 號之核心宣示。\n- **C 對**：對 §19 II 之具體限制。\n- **D 錯**：罪責原則同時拘束構成要件（故意 / 過失之心理面）、責任能力認定、量刑三層次，113 憲判 8 號之內涵即涵蓋此三面向。",
