        "**§272 殺直系血親尊親屬罪**：身分（直系血親卑親屬）為**刑罰加重事由** → 屬「**不純正身分犯**」。\n\n**刑法第 31 條第 2 項**：「**因身分或其他特定關係致刑有重輕或免除者，其無特定關係之人，科以通常之刑**。」\n\n本題：\n- A 對 A：直系血親卑親屬殺直系血親尊親屬 → §272（**加重**）。\n- 甲：不具該身分 → 依 §31 II「科以通常之刑」 → §271 普通殺人罪。\n- 甲行為態樣：教唆 → §29 教唆犯。\n\n→ 甲成立 §271 普通殺人罪之教唆犯。\n\n**比較 §31 I**：\n- §31 I 為「**純正身分犯**」之共犯規定（如公務員受賄 §121） — 無身分者擬制為共犯（得減）。\n- §31 II 為「**不純正身分犯**」之加重 / 減輕 / 免除規定 — 無身分者科以通常之刑（既不擬制亦不加重）。\n\n- **A 對**：§31 II 之經典操作。\n- **B 錯**：忽略 §31 II 之規定，誤將身分加重擴張至無身分之共犯。\n- **C 錯**：B 具身分，應論加重之 §272。\n- **D 錯**：恐嚇與本題無關。",
