      correctAnswer: "C",
      explanationMd:
        "**刑法第 51 條第 5 款**：「宣告多數有期徒刑者，**於各刑中之最長期以上，各刑合併之刑期以下**，定其刑期。但不得逾**三十年**。」\n\n**執行刑酌定之三段範圍**：\n1. **下限**：各刑中之最長期（保護「不得低於單罪最高刑」之原則）。\n2. **上限 (a)**：各刑合併之刑期（保護「不得超過各刑總和」之原則）。\n3. **絕對上限 (b)**：30 年（保護被告免於無限期累積）。\n\n本題：\n- 各刑：5 年、8 年、10 年。\n- 下限：max(5, 8, 10) = 10 年。\n- 上限：min(5 + 8 + 10, 30) = min(23, 30) = 23 年。\n- **執行刑酌定範圍：10 年 ≤ 執行刑 ≤ 23 年**。\n\n法院於此範圍內依 §57 一般量刑因素（犯罪動機、目的、手段、被害情形等）酌定。\n\n- **C 對**：§51 V 之經典操作。\n- **A 錯**：上限非「必為合計」；法院得於 10-23 年範圍內酌定。\n- **B 錯**：下限非「必為最高」；法院得於 10-23 年範圍內酌定。\n- **D 錯**：執行刑由法院酌定，非檢察官指定。",
