      questionMd:
        "我國國民甲於日本旅遊期間，竊取餐廳客人 B 所遺失之手機（價值新台幣 5,000 元）。日本竊盜罪法定刑為 10 年以下有期徒刑。甲回國後檢察官以我國 §320 竊盜罪起訴。下列關於應否適用我國刑法之審查，何者最為正確？",
