      explanationMd:
        "**刑法第 2 條第 1 項**：「行為後法律有變更者，適用行為時之法律。但行為後之法律有利於行為人者，**適用最有利於行為人之法律**。」\n\n**「最有利於行為人」之範圍**（依最高法院 105 年第 13 次刑事庭會議決議）：\n- 含「行為時法」、「裁判時法」、以及**「中間法」**（行為後至裁判前曾施行過之任一版本）。\n- 三個（或以上）版本中**選擇最有利**之版本適用。\n\n本題：\n- 行為時（107 年）：5 年以下。\n- 中間法（108-109 年）：3 年以下。\n- 裁判時（110-111 年）：5 年以下。\n- 比較：中間法 3 年最輕 → 適用中間法。\n\n此即「從新從輕原則」之延伸 — 對行為人有利之溯及，無論是新法、舊法或中間法皆可適用。\n\n- **B 對**：§2 I 但書 + 中間法理論之經典操作。\n- **A 錯**：忽略 §2 I 但書之從輕原則。\n- **C 錯**：裁判時法非當然優先；須與行為時法及中間法比較。\n- **D 錯**：法律變更非免訴事由（免訴限於時效、大赦等 §302 刑訴法所列）。",
